mapper.select:
SELECT c.id AS characterId, c.name AS characterName, c.avatar_url AS avatarUrl, c.st_avatar_url AS stAvatarUrl, c.private_card AS privateCard, c.owner_user_id AS ownerUserId, p.character_id AS overrideCharacterId, p.image_enabled AS imageEnabled, p.default_mode AS defaultMode, p.allowed_modes_json AS allowedModesJson, p.reference_source_mode AS referenceSourceMode, p.reference_images_enabled AS referenceImagesEnabled, p.negative_prompt AS negativePrompt, p.updated_at AS policyUpdatedAt FROM app_character c LEFT JOIN app_character_image_policy p ON p.character_id = c.id WHERE c.deleted_at IS NULL
AND (c.name LIKE CONCAT('%', #{keyword}, '%') OR CAST(c.id AS CHAR) = #{keyword})
ORDER BY (p.character_id IS NOT NULL) DESC, c.id DESC LIMIT #{limit} OFFSET #{offset}
